/**
 * The "Developer" wordmark as nine complete, standalone letters.
 *
 * In the master artwork the letters overlap like stickers: each one sits on
 * top of its right-hand neighbour, so only D is fully drawn and the others
 * are partly hidden. Here every hidden part has been reconstructed (each cut
 * outline continued from just before the junction curl with a lean,
 * tangent-continuous two-arc curve that follows the letter's own curvature),
 * so all nine letters are whole, smooth shapes that can move freely.
 *
 * To rebuild the artwork exactly, the letters are stacked back to front
 * (r ... D) and each letter is masked by its front neighbour's `occluder`:
 * that neighbour's silhouette grown by a uniform 6.1px outline gap. In
 * motion the occluder travels with its letter, so outlines stay even and
 * see-through and hidden parts appear whole. (Static views render the exact
 * single-piece artwork, WORDMARK_PATH, instead.)
 *
 * Units: design px in the artwork's 1264 x 1080 frame. Order: left to right.
 */
export type Letter = {
  glyph: string;
  /** bounds of the complete letter [x0, y0, x1, y1] */
  box: readonly [number, number, number, number];
  /** centroid of the visible letter [x, y] */
  centroid: readonly [number, number];
  /** the complete letter */
  d: string;
  /** this letter + its outline gap, cut out of the letter behind it */
  occluder: string | null;
};

